/*
 * The API reference (R2.0b.2): one page per public name, grouped by task. The components come
 * from the options table (src/lib/scene/options.json), which also lists their options; the other
 * public names (functions, resources and types) are here. A page's prose is
 * src/routes/content/reference/<id>.svx; a component's example is
 * src/examples/<id>-basic/<id>-basic.svelte and <id>-basic.py.
 */

import { optionsTable, optionGroups } from "../../lib/scene/options.js";

// A row of an entry's table: a parameter, or one function of a page that groups several. `python`
// is Python's spelling where snake_case of `name` is not it.
const p = (name, type, description, python) => ({ name, type, description, ...(python ? { python } : {}) });
const kebab = (name) => name.replace(/([a-z0-9])([A-Z])/g, "$1-$2").toLowerCase();

// Page ids that are not the component's name in kebab case.
const PAGE_IDS = {
  LayoutGrid: "grid", Ecdf: "ecdf-chart", Points3D: "points-3d", Arrows3D: "arrows-3d",
  Text3D: "text-3d", GeoJSON: "geojson", DAG: "dag",
};
// Python's own spelling of a name.
const PYTHON_TITLES = { LayoutGrid: "Grid", Slot: "slot" };
// Gallery examples that show a component at work.
const RELATED = {
  Plot: ["data-shortcut"], Heatmap: ["surface"], Points3D: ["frame-3d"], Points: ["symbols"], Segments: ["paths"],
  Line: ["curved-paths"], Surface: ["surface"], Arrows3D: ["paths"], Text3D: ["point-labels"], Image: ["image"],
  Theme: ["themes"], Minimap: ["timeseries"], Legend: ["guides"], Area: ["layered-signal"],
  ErrorBars: ["guides"], Data: ["data-shortcut", "constant-data", "ten-million-stars"], Provider: ["provider-earthquakes"], Interaction: ["shared-selection"],
  Bin: ["histograms"], Filter: ["transform-controls"], Sort: ["layered-signal"],
  Normalize: ["layered-signal"], Window: ["layered-signal"], Group: ["bar"], Hexbin: ["facets"],
  Stack: ["streamgraph", "stacked-percent", "bar"], Rect: ["histograms"], Prism: ["facets"], Facet: ["facets"],
  Partition: ["partition-density"], Dodge: ["swarm"], InputContext: ["inputs"], Slider: ["inputs"], Checkbox: ["inputs"],
  Button: ["inputs"], Select: ["inputs"], Playback: ["inputs", "calendar"], Simulate: ["springs"],
  Interpolate: ["transform-grid"], Slice: ["transform-slice"], Density: ["density"], Pivot: ["pivot-fold"],
  Fold: ["pivot-fold"], Join: ["join-tables"],
  Regression: ["smooth"], Contour: ["density-contours"], Delaunay: ["voronoi"], Voronoi: ["voronoi"],
  Hull: ["voronoi"], Sample: ["categories"], Summary: ["quantile-aggregate"], Calculate: ["calculate-matrix", "calculate-large"],
  Force: ["transform-force", "transform-forces"], GraphData: ["positioned-graph", "rooted-tree"], DAG: ["layered-dag"], Pack: ["packed-hierarchy"],
  Treemap: ["treemap-hierarchy"], Sankey: ["sankey-flow"], Flow: ["sankey-flow"], Routes: ["layered-dag"],
  Nodes: ["rooted-tree"], Edges: ["rooted-tree"], GeoJSON: ["geojson-globe", "earthquakes"],
  VectorTile: ["vector-tiles"], Histogram: ["histograms"], Violin: ["violin"], BoxPlot: ["box-plot"], Swarm: ["swarm"],
  Bar: ["bar"], Lollipop: ["lollipop"], RuleX: ["crosshair"], RuleY: ["crosshair"], Crosshair: ["crosshair"],
  Callout: ["annotations"], Smooth: ["smooth"], Ecdf: ["ecdf"], Polygon: ["voronoi"], DensityContour: ["density-contours"], DensityBands: ["density-contours"],
  Title: ["annotations"], Pie: ["pie", "donut", "pie-facet"], Mapping: ["shared-mappings"], Text: ["point-labels"],
  Anchor: ["before-after-arrows"], Tree: ["rooted-tree", "tree-icicle", "clustermap"], Arrows: ["rooted-tree"],
  Frame: ["nonlinear-frames"], Scene: ["linked"], Row: ["linked"], Column: ["linked"], LayoutGrid: ["linked"],
  LinkViews: ["linked"],
};

const components = Object.entries(optionsTable.components).map(([name, component]) => ({
  id: PAGE_IDS[name] ?? kebab(name), title: name, pythonTitle: (["charts", "stats"].includes(component.tier) ? component.tier + "." : "") + (PYTHON_TITLES[name] ?? name),
  group: component.group, kind: "Component", component: name, summary: component.summary,
  languages: component.languages, examples: RELATED[name] ?? [],
}));

// The other public names. `type` lists a TypeScript type's members (types.json, generated from
// publicTypes.ts); `sets` a set of the options table; `props` the parameters, in words, or, on a
// page that groups several functions (`propsTitle: "Functions"`), one row per function. Every
// runtime export of the package's entry points has a component page, a page of its name, or a
// row here (tests/unit/docs-reference.test.js); `package` marks the page of an entry point.
