for (const entry of others) {
  entry.pythonTitle ??= entry.title;
  // A JavaScript-only page keeps JavaScript's names on the Python route too.
  if (entry.languages === "js") for (const prop of entry.props ?? []) prop.python ??= prop.name;
}

// Earlier page ids render the page that replaced them.
const MOVED = {
  "ribbon": "area",
  "ambient-light": "light", "directional-light": "light",
  "hemisphere-light": "light", "point-light": "light",
  "multi-select": "select",
  "geojson-line": "geojson",
  "constant-data": "data",
  "range-slider": "slider",
  "controls": "row",
  "layout-controls": "row",
  "title-node": "title", "geo-json": "geojson", "layout-grid": "grid",
  "mark-props": "mark-options", "animation-options": "mark-options", "theme-definition": "themes",
  "scale-resources": "continuous", "categorical-literal": "categorical", "joinaggregate--quantile": "reductions",
  // TODO 137.3: removed transforms open the page of what replaces them.
  "join-aggregate": "reductions", quantile: "reductions", ecdf: "ecdf-chart", shuffle: "sample", "from-edges": "graph-data",
  "force--tree": "force", "normalize--stack--window": "normalize", "pivot--fold": "pivot",
  "sort--shuffle--sample": "sort", "rect-prism": "rect", "segments-arrows": "segments", "statistical-marks": "area",
  "raster-and-image": "image", "layout-and-lighting": "scene", "scene-python": "scene", "transforms": "bin",
  "graph-scopes": "nodes",
};
const canonical = [...components, ...others];
const aliases = Object.entries(MOVED).map(([id, target]) => ({ ...canonical.find((entry) => entry.id === target), id, hidden: true, aliasOf: target }));

export const apiEntries = [...canonical, ...aliases];
/** The content/reference page id that renders the reference entry `id`. */
export function referencePage(id) {
  return apiEntries.find((entry) => entry.id === id)?.aliasOf ?? id;
}
// The components' groups, then the package's entry points (TODO 69.13).
export const apiGroups = [...optionGroups, "Package"];
